def test_four_frozen_p0_runs(tmp_path, monkeypatch):
    # No SDK is allowed even if a model spec names a real vendor.
    import anthropic, openai
    def forbidden(*args, **kwargs):
        raise AssertionError("真实提供方不得构造")
    monkeypatch.setattr(anthropic,"AsyncAnthropic",forbidden)
    monkeypatch.setattr(openai,"AsyncOpenAI",forbidden)
    async def check():
        for name in ('A','A2','B','C'):
            config=json.loads((Path(__file__).parents[1]/f'novel/pilot_configs/exp{name}.json').read_text())
            out=tmp_path/name
            assert await run_experiment(config,out,dry_run=True,source_run=tmp_path/'A' if name=='C' else None)==0
            steps=sorted(str(p.relative_to(out)) for p in out.rglob('*.json') if isinstance((value:=json.loads(p.read_text())),dict) and 'step_key' in value)
            bodies={str(p.relative_to(out)):hashlib.sha256(p.read_bytes()).hexdigest() for p in out.rglob('chapter.md')}
            assert steps==BASELINE[name]['steps']
            assert bodies==BASELINE[name]['bodies']
    asyncio.run(check())
